CREATE FUNCTION fid.fid_execute_atomic_persistence_batch(
  batch_id text, ordered_operations jsonb, requested_atomicity text, preconditions jsonb,
  expected_repository jsonb, idempotency jsonb, audit jsonb, source_refs jsonb
) RETURNS jsonb
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY DEFINER
SET search_path = pg_catalog, fid
AS $fid_atomic_batch$
DECLARE
  v_batch_id text := batch_id; v_ordered_operations jsonb := ordered_operations;
  v_requested_atomicity text := requested_atomicity; v_preconditions jsonb := preconditions;
  v_expected_repository jsonb := expected_repository; v_idempotency jsonb := idempotency;
  v_audit jsonb := audit; v_source_refs jsonb := source_refs;
  r_operation record; r_current_revision record; r_idempotency record;
  v_operation jsonb; v_canonical_row jsonb; v_operation_index integer; v_operation_id text;
  v_persistence_id text; v_canonical_record_id text; v_record_revision integer; v_target_contract text;
  v_request_id text; v_idempotency_key text; v_request_hash text; v_event_type text; v_event_status text;
  v_source_endpoint_contract text; v_target_endpoint_contract text; v_stored_result jsonb;
  v_operation_result jsonb; v_receipt_result jsonb; v_validation_code text; v_field_path text;
  v_exception_category text; v_error_code text; v_safe_message text; v_expected_revision integer; v_observed_revision integer;
  v_constraint_name text; v_returned_sqlstate text; v_table_name text; v_column_name text;
  v_operation_results jsonb := '[]'::jsonb; v_receipt_results jsonb := '[]'::jsonb; v_audit_results jsonb := '[]'::jsonb;
  v_allowed_command_keys constant text[] := ARRAY['operationIndex','operationId','action','tableTarget','canonicalRow','auxiliaryRows','preconditions','executes']::text[];
  v_allowed_canonical_keys constant text[] := ARRAY['persistence_id','canonical_record_id','record_revision','predecessor_persistence_id','predecessor_record_id','predecessor_revision','target_contract','contract_version','schema_version','persistence_envelope','record_payload','source_refs','evidence_refs','review_refs','blocker_refs','verification','provenance','lifecycle','notes','extensions','created_at','created_by','request_id','operation_id','batch_id','idempotency_key','content_hash','status','relationship_source_contract','relationship_source_record_id','relationship_target_contract','relationship_target_record_id','relationship_type','relationship_direction']::text[];
  v_required_canonical_keys constant text[] := ARRAY['persistence_id','canonical_record_id','record_revision','target_contract','contract_version','schema_version','persistence_envelope','record_payload','source_refs','evidence_refs','review_refs','blocker_refs','verification','provenance','lifecycle','extensions','created_at','created_by','request_id','operation_id','content_hash','status']::text[];
BEGIN
  IF v_batch_id IS NULL OR v_ordered_operations IS NULL OR v_requested_atomicity IS NULL OR v_preconditions IS NULL OR v_expected_repository IS NULL OR v_idempotency IS NULL OR v_audit IS NULL OR v_source_refs IS NULL THEN
    v_validation_code := 'REQUIRED_RPC_ARGUMENT_MISSING'; v_field_path := 'rpc';
    RETURN pg_catalog.jsonb_build_object('status','FAILED','batchId',v_batch_id,'requestId',NULL,'operationResults','[]'::jsonb,'achievedAtomicity',NULL,'commitState','NOT_COMMITTED','rollbackState','NOT_REQUIRED','replayed',false,'errors',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('code',v_validation_code,'message','The persistence request failed governed validation.','fieldPath',v_field_path,'operationIndex',NULL)),'effectReceipts','[]'::jsonb,'auditEventIds','[]'::jsonb,'idempotency',NULL,'metadata','{}'::jsonb);
  END IF;
  IF pg_catalog.jsonb_typeof(v_ordered_operations) IS DISTINCT FROM 'array' OR pg_catalog.jsonb_typeof(v_source_refs) IS DISTINCT FROM 'array' OR pg_catalog.jsonb_array_length(v_ordered_operations)=0 THEN
    v_validation_code := 'MAPPED_COMMAND_STRUCTURE'; v_field_path := 'ordered_operations';
    RETURN pg_catalog.jsonb_build_object('status','FAILED','batchId',v_batch_id,'requestId',v_audit->>'requestId','operationResults','[]'::jsonb,'achievedAtomicity',NULL,'commitState','NOT_COMMITTED','rollbackState','NOT_REQUIRED','replayed',false,'errors',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('code',v_validation_code,'message','The persistence request failed governed validation.','fieldPath',v_field_path,'operationIndex',NULL)),'effectReceipts','[]'::jsonb,'auditEventIds','[]'::jsonb,'idempotency',NULL,'metadata','{}'::jsonb);
  END IF;
  v_request_id:=v_audit->>'requestId'; v_idempotency_key:=v_idempotency->>'idempotencyKey'; v_request_hash:=v_idempotency->>'requestHash';
  IF v_request_id IS NULL OR v_request_id='' OR v_idempotency_key IS NULL OR v_idempotency_key='' OR v_request_hash IS NULL OR v_request_hash='' THEN v_exception_category:='VALIDATION';v_validation_code:='REQUIRED_DATABASE_COLUMNS';RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed validation';END IF;
  SELECT i.idempotency_key,i.request_hash,i.result_status,i.result_payload INTO r_idempotency FROM fid.fid_persistence_idempotency AS i WHERE i.idempotency_key=v_idempotency_key FOR UPDATE;
  IF FOUND THEN
    IF r_idempotency.request_hash IS DISTINCT FROM v_request_hash THEN v_exception_category:='IDEMPOTENCY_FINGERPRINT';RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed idempotency conflict';END IF;
    IF r_idempotency.result_status='COMMITTED' AND r_idempotency.result_payload IS NOT NULL THEN v_event_type:='BATCH_REPLAYED';v_event_status:='REPLAYED';v_safe_message:='Persistence batch replayed its stored result.';RETURN pg_catalog.jsonb_set(r_idempotency.result_payload,'{replayed}','true'::jsonb,false);END IF;
    IF r_idempotency.result_status='PENDING' THEN v_exception_category:='IDEMPOTENCY_FINGERPRINT';RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed pending idempotency conflict';END IF;
  END IF;
  IF NOT FOUND OR r_idempotency.result_status='ROLLED_BACK' THEN
    INSERT INTO fid.fid_persistence_idempotency(idempotency_key,request_id,batch_id,request_hash,result_status,first_seen_at,outcome_indeterminate) VALUES(v_idempotency_key,v_request_id,v_batch_id,v_request_hash,'PENDING',(v_audit->>'occurredAt')::timestamptz,false)
    ON CONFLICT (idempotency_key) DO NOTHING;
    SELECT i.idempotency_key,i.request_hash,i.result_status,i.result_payload INTO r_idempotency FROM fid.fid_persistence_idempotency AS i WHERE i.idempotency_key=v_idempotency_key FOR UPDATE;
    IF r_idempotency.request_hash IS DISTINCT FROM v_request_hash THEN v_exception_category:='IDEMPOTENCY_FINGERPRINT';RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed concurrent idempotency conflict';END IF;
    IF r_idempotency.result_status='COMMITTED' THEN RETURN pg_catalog.jsonb_set(r_idempotency.result_payload,'{replayed}','true'::jsonb,false);END IF;
  END IF;
  FOR r_operation IN SELECT e.value AS operation,(e.ordinality-1)::integer AS original_index FROM pg_catalog.jsonb_array_elements(v_ordered_operations) WITH ORDINALITY AS e(value,ordinality) ORDER BY e.ordinality LOOP
    v_operation:=r_operation.operation;v_operation_index:=r_operation.original_index;v_canonical_row:=v_operation->'canonicalRow';
    IF pg_catalog.jsonb_typeof(v_operation) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM pg_catalog.jsonb_object_keys(v_operation) AS k(key_name) WHERE NOT(k.key_name=ANY(v_allowed_command_keys))) OR NOT(v_operation?'operationIndex') OR pg_catalog.jsonb_typeof(v_operation->'operationIndex') IS DISTINCT FROM 'number' OR (v_operation->>'operationIndex')::integer IS DISTINCT FROM v_operation_index OR NOT(v_operation?'operationId') OR pg_catalog.jsonb_typeof(v_operation->'operationId') IS DISTINCT FROM 'string' OR v_operation->>'operationId'='' OR NOT(v_operation?'action') OR v_operation->>'action' NOT IN('CREATE','APPEND_REVISION') OR NOT(v_operation?'tableTarget') OR v_operation->>'tableTarget' IS DISTINCT FROM 'fid_record_revisions' OR NOT(v_operation?'canonicalRow') OR pg_catalog.jsonb_typeof(v_canonical_row) IS DISTINCT FROM 'object' OR NOT(v_operation?'auxiliaryRows') OR pg_catalog.jsonb_typeof(v_operation->'auxiliaryRows') IS DISTINCT FROM 'array' OR v_operation->'auxiliaryRows' IS DISTINCT FROM '[]'::jsonb OR NOT(v_operation?'preconditions') OR pg_catalog.jsonb_typeof(v_operation->'preconditions') IS DISTINCT FROM 'array' OR NOT(v_operation?'executes') OR pg_catalog.jsonb_typeof(v_operation->'executes') IS DISTINCT FROM 'boolean' OR v_operation->'executes' IS DISTINCT FROM 'false'::jsonb THEN v_exception_category:='VALIDATION';v_validation_code:='VALIDATION_FAILURE';RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed command validation';END IF;
    IF EXISTS(SELECT 1 FROM pg_catalog.jsonb_object_keys(v_canonical_row) AS k(key_name) WHERE NOT(k.key_name=ANY(v_allowed_canonical_keys))) OR EXISTS(SELECT 1 FROM pg_catalog.unnest(v_required_canonical_keys) AS required(key_name) WHERE NOT(v_canonical_row?required.key_name) OR v_canonical_row->required.key_name='null'::jsonb OR (pg_catalog.jsonb_typeof(v_canonical_row->required.key_name)='string' AND v_canonical_row->>required.key_name='')) THEN v_exception_category:='VALIDATION';v_validation_code:='REQUIRED_DATABASE_COLUMNS';RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed required field validation';END IF;
    IF v_batch_id IS DISTINCT FROM v_canonical_row->>'batch_id' THEN v_exception_category:='VALIDATION';v_validation_code:='BATCH_ID_MISMATCH';RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed batch mismatch';END IF;
    IF v_operation->>'operationId' IS DISTINCT FROM v_canonical_row->>'operation_id' THEN v_exception_category:='VALIDATION';v_validation_code:='OPERATION_ID_MISMATCH';RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed operation mismatch';END IF;
    IF v_request_id IS DISTINCT FROM v_canonical_row->>'request_id' THEN v_exception_category:='VALIDATION';v_validation_code:='REQUEST_ID_MISMATCH';RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed request mismatch';END IF;
    IF (v_audit->>'occurredAt')::timestamptz IS DISTINCT FROM (v_canonical_row->>'created_at')::timestamptz THEN v_exception_category:='VALIDATION';v_validation_code:='CREATED_AT_AUDIT_TIME_MISMATCH';RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed timestamp mismatch';END IF;
    IF v_source_refs IS DISTINCT FROM v_canonical_row->'source_refs' THEN v_exception_category:='VALIDATION';v_validation_code:='SOURCE_REFS_MISMATCH';RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed source mismatch';END IF;
    IF v_idempotency_key IS DISTINCT FROM v_canonical_row->>'idempotency_key' THEN v_exception_category:='VALIDATION';v_validation_code:='VALIDATION_FAILURE';RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed idempotency key mismatch';END IF;
    IF EXISTS(SELECT 1 FROM pg_catalog.unnest(ARRAY['source_refs','evidence_refs','review_refs','blocker_refs']::text[]) a(array_name) WHERE pg_catalog.jsonb_typeof(v_canonical_row->a.array_name) IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(v_canonical_row->a.array_name) element WHERE pg_catalog.jsonb_typeof(element) IS DISTINCT FROM 'string')) THEN v_exception_category:='MALFORMED_PAYLOAD';RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='governed malformed array';END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(v_ordered_operations) AS duplicate_operation GROUP BY duplicate_operation->>'operationId' HAVING pg_catalog.count(*)>1) OR EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(v_ordered_operations) AS duplicate_operation GROUP BY duplicate_operation->'canonicalRow'->>'target_contract',duplicate_operation->'canonicalRow'->>'canonical_record_id' HAVING pg_catalog.count(*)>1) THEN v_exception_category:='VALIDATION';v_validation_code:='VALIDATION_FAILURE';RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed duplicate operation';END IF;
  FOR r_operation IN SELECT e.value AS operation,(e.ordinality-1)::integer AS original_index,e.value->'canonicalRow'->>'target_contract' AS target_contract,e.value->'canonicalRow'->>'canonical_record_id' AS canonical_record_id FROM pg_catalog.jsonb_array_elements(v_ordered_operations) WITH ORDINALITY AS e(value,ordinality) ORDER BY target_contract ASC,canonical_record_id ASC,original_index ASC LOOP
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(r_operation.target_contract||':'||r_operation.canonical_record_id,0::bigint));
  END LOOP;
  v_event_type:='BATCH_RECEIVED';v_event_status:='RECEIVED';
  INSERT INTO fid.fid_persistence_batches(batch_id,request_id,expected_operation_count,requested_atomicity,actor_ref,source_refs,lifecycle,notes,started_at,committed_operation_count,failed_operation_count,commit_state,rollback_state) VALUES(v_batch_id,v_request_id,pg_catalog.jsonb_array_length(v_ordered_operations),v_requested_atomicity,v_audit->>'actorRef',v_source_refs,'{}'::jsonb,NULL,(v_audit->>'occurredAt')::timestamptz,0,0,'PROCESSING','NOT_REQUIRED');
  INSERT INTO fid.fid_persistence_audit_events(event_id,event_type,request_ref,batch_ref,repository_ref,actor_ref,category,severity,message,occurred_at,details,source_refs) VALUES(v_batch_id||':BATCH_RECEIVED:batch','BATCH_RECEIVED',v_request_id,v_batch_id,v_expected_repository->>'repositoryRef',v_audit->>'actorRef','PERSISTENCE','INFO','Persistence batch received.',(v_audit->>'occurredAt')::timestamptz,pg_catalog.jsonb_build_object('batchId',v_batch_id,'operationId',NULL,'eventType','BATCH_RECEIVED','status','RECEIVED'),v_source_refs);
  v_audit_results:=v_audit_results||pg_catalog.jsonb_build_array(v_batch_id||':BATCH_RECEIVED:batch');
  INSERT INTO fid.fid_persistence_audit_events(event_id,event_type,request_ref,batch_ref,repository_ref,actor_ref,category,severity,message,occurred_at,details,source_refs) VALUES(v_batch_id||':BATCH_VALIDATED:batch','BATCH_VALIDATED',v_request_id,v_batch_id,v_expected_repository->>'repositoryRef',v_audit->>'actorRef','PERSISTENCE','INFO','Persistence batch validation completed.',(v_audit->>'occurredAt')::timestamptz,pg_catalog.jsonb_build_object('batchId',v_batch_id,'operationId',NULL,'eventType','BATCH_VALIDATED','status','VALIDATED'),v_source_refs);
  v_audit_results:=v_audit_results||pg_catalog.jsonb_build_array(v_batch_id||':BATCH_VALIDATED:batch');
  FOR r_operation IN SELECT e.value AS operation,(e.ordinality-1)::integer AS original_index FROM pg_catalog.jsonb_array_elements(v_ordered_operations) WITH ORDINALITY AS e(value,ordinality) ORDER BY e.ordinality LOOP
    v_operation:=r_operation.operation;v_operation_index:=r_operation.original_index;v_canonical_row:=v_operation->'canonicalRow';v_operation_id:=v_operation->>'operationId';v_persistence_id:=v_canonical_row->>'persistence_id';v_canonical_record_id:=v_canonical_row->>'canonical_record_id';v_record_revision:=(v_canonical_row->>'record_revision')::integer;v_target_contract:=v_canonical_row->>'target_contract';
    SELECT rr.persistence_id,rr.target_contract,rr.canonical_record_id,rr.record_revision,rr.predecessor_persistence_id,rr.content_hash,rr.status INTO r_current_revision FROM fid.fid_record_revisions AS rr WHERE rr.target_contract=v_target_contract AND rr.canonical_record_id=v_canonical_record_id ORDER BY rr.record_revision DESC NULLS LAST LIMIT 1 FOR UPDATE;
    IF v_operation->>'action'='CREATE' AND FOUND THEN v_exception_category:='DUPLICATE_LOGICAL_RECORD';RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed duplicate record';END IF;
    IF v_operation->>'action'='CREATE' AND (v_record_revision IS DISTINCT FROM 1 OR NOT(v_canonical_row?'predecessor_persistence_id') OR v_canonical_row->'predecessor_persistence_id' IS DISTINCT FROM 'null'::jsonb OR NOT(v_canonical_row?'predecessor_record_id') OR v_canonical_row->'predecessor_record_id' IS DISTINCT FROM 'null'::jsonb OR NOT(v_canonical_row?'predecessor_revision') OR v_canonical_row->'predecessor_revision' IS DISTINCT FROM 'null'::jsonb) THEN v_exception_category:='VALIDATION';v_validation_code:='VALIDATION_FAILURE';RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed create semantics validation';END IF;
    IF v_operation->>'action'='APPEND_REVISION' AND NOT FOUND THEN v_exception_category:='PREDECESSOR_NOT_FOUND';v_expected_revision:=v_record_revision-1;v_observed_revision:=NULL;RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed predecessor not found';END IF;
    IF v_operation->>'action'='APPEND_REVISION' AND v_record_revision IS DISTINCT FROM r_current_revision.record_revision+1 THEN v_exception_category:='REVISION_DISCONTINUITY';v_expected_revision:=r_current_revision.record_revision+1;v_observed_revision:=v_record_revision;RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed revision discontinuity';END IF;
    IF v_operation->>'action'='APPEND_REVISION' AND (v_canonical_row->>'predecessor_persistence_id' IS DISTINCT FROM r_current_revision.persistence_id OR v_canonical_row->>'predecessor_record_id' IS DISTINCT FROM v_canonical_record_id OR (v_canonical_row->>'predecessor_revision')::integer IS DISTINCT FROM r_current_revision.record_revision OR r_current_revision.target_contract IS DISTINCT FROM v_target_contract OR r_current_revision.canonical_record_id IS DISTINCT FROM v_canonical_record_id) THEN v_exception_category:='PREDECESSOR_MISMATCH';v_expected_revision:=r_current_revision.record_revision;v_observed_revision:=(v_canonical_row->>'predecessor_revision')::integer;RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed predecessor mismatch';END IF;
    IF v_target_contract='FootballRelationship' THEN
      v_source_endpoint_contract:=CASE v_canonical_row->>'relationship_source_contract' WHEN 'CoachProfile' THEN 'PersonProfile' WHEN 'ExecutiveProfile' THEN 'PersonProfile' WHEN 'ScoutProfile' THEN 'PersonProfile' ELSE v_canonical_row->>'relationship_source_contract' END;
      v_target_endpoint_contract:=CASE v_canonical_row->>'relationship_target_contract' WHEN 'CoachProfile' THEN 'PersonProfile' WHEN 'ExecutiveProfile' THEN 'PersonProfile' WHEN 'ScoutProfile' THEN 'PersonProfile' ELSE v_canonical_row->>'relationship_target_contract' END;
      IF v_source_endpoint_contract NOT IN('FootballEntity','PersonProfile','PlayerProfile','ProspectProfile','OrganizationProfile','TeamProfile') OR v_target_endpoint_contract NOT IN('FootballEntity','PersonProfile','PlayerProfile','ProspectProfile','OrganizationProfile','TeamProfile') OR v_canonical_row->>'relationship_source_contract'='FootballRelationship' OR v_canonical_row->>'relationship_target_contract'='FootballRelationship' OR NOT EXISTS(SELECT 1 FROM fid.fid_record_revisions AS source_endpoint WHERE source_endpoint.target_contract=v_source_endpoint_contract AND source_endpoint.canonical_record_id=v_canonical_row->>'relationship_source_record_id') OR NOT EXISTS(SELECT 1 FROM fid.fid_record_revisions AS target_endpoint WHERE target_endpoint.target_contract=v_target_endpoint_contract AND target_endpoint.canonical_record_id=v_canonical_row->>'relationship_target_record_id') THEN v_exception_category:='RELATIONSHIP_ENDPOINT';RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='governed relationship endpoint';END IF;
    END IF;
    INSERT INTO fid.fid_record_revisions SELECT v_canonical_row->>'persistence_id',v_canonical_row->>'canonical_record_id',(v_canonical_row->>'record_revision')::integer,v_canonical_row->>'predecessor_persistence_id',v_canonical_row->>'predecessor_record_id',(v_canonical_row->>'predecessor_revision')::integer,v_canonical_row->>'target_contract',v_canonical_row->>'contract_version',v_canonical_row->>'schema_version',v_canonical_row->'persistence_envelope',v_canonical_row->'record_payload',ARRAY(SELECT x.element_value FROM pg_catalog.jsonb_array_elements_text(v_canonical_row->'source_refs') WITH ORDINALITY AS x(element_value,element_order) ORDER BY x.element_order),ARRAY(SELECT x.element_value FROM pg_catalog.jsonb_array_elements_text(v_canonical_row->'evidence_refs') WITH ORDINALITY AS x(element_value,element_order) ORDER BY x.element_order),ARRAY(SELECT x.element_value FROM pg_catalog.jsonb_array_elements_text(v_canonical_row->'review_refs') WITH ORDINALITY AS x(element_value,element_order) ORDER BY x.element_order),ARRAY(SELECT x.element_value FROM pg_catalog.jsonb_array_elements_text(v_canonical_row->'blocker_refs') WITH ORDINALITY AS x(element_value,element_order) ORDER BY x.element_order),v_canonical_row->'verification',v_canonical_row->'provenance',v_canonical_row->'lifecycle',v_canonical_row->>'notes',v_canonical_row->'extensions',(v_canonical_row->>'created_at')::timestamptz,v_canonical_row->>'created_by',v_canonical_row->>'request_id',v_canonical_row->>'operation_id',v_batch_id,v_canonical_row->>'idempotency_key',v_canonical_row->>'content_hash',v_canonical_row->>'status',v_canonical_row->>'relationship_source_contract',v_canonical_row->>'relationship_source_record_id',v_canonical_row->>'relationship_target_contract',v_canonical_row->>'relationship_target_record_id',v_canonical_row->>'relationship_type',v_canonical_row->>'relationship_direction';
    INSERT INTO fid.fid_persistence_batch_operations VALUES(v_batch_id,v_operation_id,v_operation_index,v_operation->>'action',v_persistence_id,v_canonical_record_id,v_batch_id||':'||v_operation_id||':result',v_record_revision,v_operation->'preconditions',v_operation);
    v_operation_result:=pg_catalog.jsonb_build_object('status','COMMITTED','operationId',v_operation_id,'persistenceId',v_persistence_id,'recordId',v_canonical_record_id,'revision',v_record_revision,'committed',true);v_operation_results:=v_operation_results||pg_catalog.jsonb_build_array(v_operation_result);
    v_receipt_result:=pg_catalog.jsonb_build_object('receiptId',v_batch_id||':'||v_operation_id||':receipt','operationId',v_operation_id,'committed',true);v_receipt_results:=v_receipt_results||pg_catalog.jsonb_build_array(v_receipt_result);
    INSERT INTO fid.fid_persistence_effect_receipts VALUES(v_batch_id||':'||v_operation_id||':receipt',v_request_id,v_batch_id,v_operation_id,v_expected_repository->>'repositoryRef',v_operation->>'action',v_persistence_id,v_canonical_record_id,v_canonical_row->>'predecessor_persistence_id','COMMITTED','TRANSACTIONAL',v_audit->>'actorRef',NULL,v_record_revision,true,true,(v_audit->>'occurredAt')::timestamptz,v_canonical_row->'verification',pg_catalog.to_jsonb(ARRAY[v_batch_id||':OPERATION_COMMITTED:'||v_operation_id]::text[]));
    INSERT INTO fid.fid_persistence_audit_events VALUES(v_batch_id||':OPERATION_COMMITTED:'||v_operation_id,'OPERATION_COMMITTED',v_request_id,v_batch_id,v_operation_id,v_expected_repository->>'repositoryRef',v_audit->>'actorRef','PERSISTENCE','INFO','Persistence operation committed.',NULL,(v_audit->>'occurredAt')::timestamptz,pg_catalog.jsonb_build_object('batchId',v_batch_id,'operationId',v_operation_id,'eventType','OPERATION_COMMITTED','status','COMMITTED'),v_source_refs);
    v_audit_results:=v_audit_results||pg_catalog.jsonb_build_array(v_batch_id||':OPERATION_COMMITTED:'||v_operation_id);
  END LOOP;
  INSERT INTO fid.fid_persistence_audit_events(event_id,event_type,request_ref,batch_ref,repository_ref,actor_ref,category,severity,message,occurred_at,details,source_refs) VALUES(v_batch_id||':BATCH_COMMITTED:batch','BATCH_COMMITTED',v_request_id,v_batch_id,v_expected_repository->>'repositoryRef',v_audit->>'actorRef','PERSISTENCE','INFO','Persistence batch committed.',(v_audit->>'occurredAt')::timestamptz,pg_catalog.jsonb_build_object('batchId',v_batch_id,'operationId',NULL,'eventType','BATCH_COMMITTED','status','COMMITTED'),v_source_refs);v_audit_results:=v_audit_results||pg_catalog.jsonb_build_array(v_batch_id||':BATCH_COMMITTED:batch');
  v_stored_result:=pg_catalog.jsonb_build_object('status','COMMITTED','batchId',v_batch_id,'requestId',v_request_id,'operationResults',v_operation_results,'achievedAtomicity','TRANSACTIONAL','commitState','COMMITTED','rollbackState','NOT_REQUIRED','replayed',false,'errors','[]'::jsonb,'effectReceipts',v_receipt_results,'auditEventIds',v_audit_results,'idempotency',pg_catalog.jsonb_build_object('idempotencyKey',v_idempotency_key,'requestHash',v_request_hash),'metadata',pg_catalog.jsonb_build_object('operationCount',pg_catalog.jsonb_array_length(v_ordered_operations)));
  UPDATE fid.fid_persistence_batches AS b SET completed_at=(v_audit->>'occurredAt')::timestamptz,committed_operation_count=pg_catalog.jsonb_array_length(v_ordered_operations),achieved_atomicity='TRANSACTIONAL',commit_state='COMMITTED',rollback_state='NOT_REQUIRED' WHERE b.batch_id=v_batch_id;
  UPDATE fid.fid_persistence_idempotency AS i SET result_status='COMMITTED',completed_at=(v_audit->>'occurredAt')::timestamptz,result_payload=v_stored_result WHERE i.idempotency_key=v_idempotency_key;
  RETURN v_stored_result;
EXCEPTION
  WHEN SQLSTATE 'P0001' OR unique_violation OR foreign_key_violation OR check_violation OR invalid_text_representation OR invalid_datetime_format OR invalid_parameter_value THEN
    GET STACKED DIAGNOSTICS v_returned_sqlstate=RETURNED_SQLSTATE,v_constraint_name=CONSTRAINT_NAME,v_table_name=TABLE_NAME,v_column_name=COLUMN_NAME;
    IF v_exception_category='VALIDATION' THEN v_error_code:=pg_catalog.coalesce(v_validation_code,'VALIDATION_FAILURE');v_safe_message:='The persistence request failed governed validation.';
    ELSIF v_exception_category='PREDECESSOR_NOT_FOUND' THEN v_error_code:='PREDECESSOR_NOT_FOUND';v_safe_message:='The current revision required for append does not exist.';
    ELSIF v_exception_category='PREDECESSOR_MISMATCH' THEN v_error_code:='PREDECESSOR_MISMATCH';v_safe_message:='The predecessor does not match the locked current revision.';
    ELSIF v_exception_category='REVISION_DISCONTINUITY' THEN v_error_code:='REVISION_DISCONTINUITY';v_safe_message:='The requested revision is not the immediate next revision.';
    ELSIF v_exception_category='IDEMPOTENCY_FINGERPRINT' THEN v_error_code:='IDEMPOTENCY_CONFLICT';v_safe_message:='The idempotency key was used for a different request.';
    ELSIF v_exception_category='RELATIONSHIP_ENDPOINT' THEN v_error_code:='RELATIONSHIP_ENDPOINT_MISSING';v_safe_message:='A required relationship endpoint does not exist.';
    ELSIF v_exception_category='DUPLICATE_LOGICAL_RECORD' OR (v_returned_sqlstate='23505' AND v_constraint_name='fid_record_revisions_pk') THEN v_error_code:='DUPLICATE_RECORD_REVISION';v_safe_message:='The logical record already exists.';
    ELSIF v_exception_category='DUPLICATE_REVISION' OR (v_returned_sqlstate='23505' AND v_constraint_name='fid_record_revision_unique') THEN v_exception_category:='DUPLICATE_REVISION';v_error_code:='DUPLICATE_RECORD_REVISION';v_safe_message:='The requested revision already exists.';
    ELSIF v_returned_sqlstate IN('23503','23514','23505') THEN v_exception_category:='DATABASE_CONSTRAINT';v_error_code:='VALIDATION_FAILURE';v_safe_message:='A governed persistence constraint was not satisfied.';
    ELSIF v_exception_category='MALFORMED_PAYLOAD' OR v_returned_sqlstate IN('22P02','22007','22023') THEN v_exception_category:='MALFORMED_PAYLOAD';v_error_code:='VALIDATION_FAILURE';v_safe_message:='The persistence payload is malformed.';
    ELSE v_exception_category:='UNEXPECTED_INTERNAL';v_error_code:='UNKNOWN';v_safe_message:='The persistence operation could not be completed.';END IF;
    v_event_type:=CASE WHEN v_error_code IN('PREDECESSOR_NOT_FOUND','PREDECESSOR_MISMATCH','REVISION_DISCONTINUITY','IDEMPOTENCY_CONFLICT','DUPLICATE_RECORD_REVISION','RELATIONSHIP_ENDPOINT_MISSING') THEN 'BATCH_CONFLICT' ELSE 'BATCH_FAILED' END;v_event_status:=CASE WHEN v_event_type='BATCH_CONFLICT' THEN 'CONFLICT' ELSE 'FAILED' END;
    RETURN pg_catalog.jsonb_build_object('status',v_event_status,'batchId',v_batch_id,'requestId',v_request_id,'operationResults','[]'::jsonb,'achievedAtomicity',NULL,'commitState','NOT_COMMITTED','rollbackState','ROLLED_BACK','replayed',false,'errors',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('code',v_error_code,'message',v_safe_message,'operationIndex',v_operation_index,'operationId',v_operation_id,'targetContract',v_target_contract,'canonicalRecordId',v_canonical_record_id,'expectedRevision',v_expected_revision,'observedRevision',v_observed_revision)),'effectReceipts','[]'::jsonb,'auditEventIds','[]'::jsonb,'idempotency',NULL,'metadata',pg_catalog.jsonb_build_object('transientAuditEvent',pg_catalog.jsonb_build_object('eventType',v_event_type,'message',CASE v_event_type WHEN 'BATCH_CONFLICT' THEN 'Persistence batch encountered a governed conflict.' ELSE 'Persistence batch could not be completed.' END),'rollbackEvent',pg_catalog.jsonb_build_object('eventType','BATCH_ROLLED_BACK','message','Persistence batch was rolled back.')));
  WHEN OTHERS THEN
    v_exception_category:='UNEXPECTED_INTERNAL';v_event_type:='BATCH_FAILED';v_event_status:='FAILED';
    RETURN pg_catalog.jsonb_build_object('status','FAILED','batchId',v_batch_id,'requestId',v_request_id,'operationResults','[]'::jsonb,'achievedAtomicity',NULL,'commitState','NOT_COMMITTED','rollbackState','ROLLED_BACK','replayed',false,'errors',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('code','UNKNOWN','message','The persistence operation could not be completed.')),'effectReceipts','[]'::jsonb,'auditEventIds','[]'::jsonb,'idempotency',NULL,'metadata',pg_catalog.jsonb_build_object('transientAuditEvent',pg_catalog.jsonb_build_object('eventType','BATCH_FAILED','message','Persistence batch could not be completed.'),'rollbackEvent',pg_catalog.jsonb_build_object('eventType','BATCH_ROLLED_BACK','message','Persistence batch was rolled back.')));
END
$fid_atomic_batch$;
ALTER FUNCTION fid.fid_execute_atomic_persistence_batch(text,jsonb,text,jsonb,jsonb,jsonb,jsonb,jsonb) OWNER TO fid_function_owner;
